import{_ as t,o as a,c as i,a7 as s}from"./chunks/framework.BJyR0VjM.js";const u=JSON.parse('{"title":"What is YggUtils?","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/what-is-yggutils.md","filePath":"documentation/what-is-yggutils.md"}'),o={name:"documentation/what-is-yggutils.md"};function r(n,e,l,h,g,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="what-is-yggutils" tabindex="-1">What is YggUtils? <a class="header-anchor" href="#what-is-yggutils" aria-label="Permalink to “What is YggUtils?”">​</a></h1><p>YggUtils is a lightweight Java server wrapper that injects <a href="https://github.com/yushijinhun/authlib-injector" target="_blank" rel="noreferrer">authlib-injector</a> into any Minecraft server&#39;s JVM at launch — enabling custom Yggdrasil authentication on hosting environments where you cannot set JVM arguments directly.</p><div class="tip custom-block" style="padding-top:8px;"><p><strong>Just want to get running?</strong> Head to the <a href="./getting-started">Getting Started</a> page.</p></div><h2 id="the-problem-it-solves" tabindex="-1">The Problem It Solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to “The Problem It Solves”">​</a></h2><p>Most Minecraft hosting panels don&#39;t let you modify JVM startup flags. Running a private network with a custom auth server (like <a href="https://littleskin.cn" target="_blank" rel="noreferrer">LittleSkin</a> or a self-hosted backend) normally requires adding a <code>-javaagent</code> flag to the JVM — something many shared hosts simply don&#39;t expose.</p><p>YggUtils wraps your server JAR and handles the agent injection itself, so you only need to run one JAR.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How It Works”">​</a></h2><p>When you run YggUtils, it:</p><ol><li>Ensures <code>authlib-injector</code> is downloaded and available locally</li><li>Reads your configuration to get the auth server URL and server JAR name</li><li>Launches your server JAR with the <code>-javaagent</code> flag injected automatically</li><li>Forwards your console input to the server and streams its output back to you</li><li>Restarts the server automatically if it crashes</li></ol><p>From the outside, it behaves exactly like running the server directly.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to “Key Features”">​</a></h2><ul><li><strong>Authlib Injector Fetching</strong> — downloads and manages <code>authlib-injector.jar</code> automatically; no manual installation needed</li><li><strong>Dynamic Launch Configuration</strong> — a simple YAML config file controls which auth server and JAR to use</li><li><strong>Native Console Interface</strong> — full two-way console forwarding; commands you type go straight to the server</li><li><strong>Auto-Restart</strong> — on a non-zero exit (crash), YggUtils waits 3 seconds and relaunches the server</li><li><strong>Silent Operation</strong> — no wrapper noise in your console; output is passed through exactly as the server produces it</li></ul><h2 id="what-yggutils-is-not" tabindex="-1">What YggUtils Is Not <a class="header-anchor" href="#what-yggutils-is-not" aria-label="Permalink to “What YggUtils Is Not”">​</a></h2><p>YggUtils is not an authentication server — it doesn&#39;t implement the Yggdrasil API itself. It simply redirects your Minecraft server&#39;s auth calls to whichever server you configure. You&#39;ll need a separately hosted Yggdrasil-compatible auth backend.</p>',14)])])}const p=t(o,[["render",r]]);export{u as __pageData,p as default};
